mongo_query:
db.TV_Channel.aggregate([{
  "$lookup": {
    "from": "Cartoon",
    "let": {
      "id": "$id"
    },
    "pipeline": [
      {
        "$match": {
          "$and": [
            {
              "$expr": {
                "$eq": [
                  "$$id",
                  "$Channel"
                ]
              }
            },
            {
              "Title": "The Rise of the Blue Beetle!"
            }
          ]
        }
      }
    ],
    "as": "T2"
  }
},{
  "$unwind": {
    "path": "$T2",
    "preserveNullAndEmptyArrays": false
  }
},{
  "$project": {
    "_id": 0,
    "series_name": 1
  }
}])

